-- 0051_osm_football_poland.sql — Boiska piłki nożnej z OSM: cała Polska
-- WYGENEROWANE: scripts/osm-poland/sport-import.mjs — nie edytować ręcznie.
-- Liczba boisk: 27670
-- Idempotentne (on conflict aktualizuje sport, geom; nazwy istniejących bez zmian).
-- ═══════════════════════════════════════════════════════════════════════════


on conflict (osm_type, osm_id) where osm_type is not null and osm_id is not null
do update set
  sport = (
    select string_agg(s, ';' order by s)
    from (
      select distinct trim(x) as s
      from unnest(string_to_array(coalesce(public.fields.sport, '') || ';' || excluded.sport, ';')) as x
      where trim(x) <> ''
    ) u
  ),
  geom = excluded.geom,
  updated_at = now();

notify pgrst, 'reload schema';
